"""Small self-contained HTML views. No remote fonts, assets or scripts."""
import html

STYLE = '''
:root{color-scheme:dark;--bg:#101318;--card:#191f27;--line:#303c4a;--ink:#edf1f5;--muted:#adc0d3;--accent:#8ed5bf}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 system-ui,sans-serif}main{max-width:620px;margin:6vh auto;padding:24px}article{padding:28px;border:1px solid var(--line);border-radius:16px;background:var(--card)}.brand{font-size:14px;font-weight:700;letter-spacing:.12em;color:var(--accent)}h1{font-size:30px;line-height:1.15;margin:14px 0}p{color:var(--muted)}label{display:block;margin:22px 0 8px;font-weight:600}input,button{font:inherit;min-height:48px;border-radius:8px}input{width:100%;padding:12px;background:var(--bg);color:var(--ink);border:1px solid var(--line)}input:focus,button:focus-visible{outline:3px solid var(--accent);outline-offset:3px}button{margin-top:18px;width:100%;background:var(--accent);color:#10251f;border:0;font-weight:700;cursor:pointer}.facts{padding:14px 16px;border:1px solid var(--line);border-radius:8px;overflow-wrap:anywhere}.facts dt{color:var(--muted);font-size:13px}.facts dd{margin:0 0 10px}.facts dd:last-child{margin:0}code{font:14px ui-monospace,monospace}.small{font-size:13px}.warning{border-left:3px solid var(--accent);padding-left:14px}a{color:var(--accent)}@media(max-width:480px){main{margin:12px auto;padding:16px}article{padding:20px}h1{font-size:26px}}
'''
HEADERS = {'Cache-Control':'no-store','Referrer-Policy':'no-referrer','X-Frame-Options':'DENY','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"}

def authorize(client,scope,hidden):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Authorize dot-mcp</title><style>{STYLE}</style></head><body><main><article><div class="brand">DOT-MCP / CONNECT</div><h1>Connect your assistant</h1><p>Approve this connection only if you started it in your assistant's settings.</p><dl class="facts"><dt>Client</dt><dd>{html.escape(client)}</dd><dt>Requested access</dt><dd><code>{html.escape(scope)}</code></dd></dl><p class="warning">This grants owner access to local tools, including shell commands and files. Only connect assistants you trust.</p><form method="post">{hidden}<label for="owner_secret">Owner secret</label><input id="owner_secret" type="password" name="owner_secret" autocomplete="off" required autofocus spellcheck="false" placeholder="Enter directly, never in chat"><button type="submit">Approve connection</button></form><p class="small">Your secret stays out of the redirect URL. To cancel, close this tab without approving.</p></article></main></body></html>'''
